window.COURSE = {"version": 2, "totalLessons": 20, "lessons": [{"id": "L1", "title": "Uma ideia que vale levar para casa", "minutes": 60, "outcome": "Definir sua ideia central em 12–15 palavras e entender storytelling científico.", "study": ["Storytelling científico não é inventar: é organizar a verdade como transformação.", "Uma palestra excelente muda algo no público: entendimento, decisão, prioridade ou ação.", "Você não precisa ser engraçado. Precisa ser claro. Clareza vira autoridade.", "Storytelling (modelo simples): realidade atual → tensão → virada → caminho → fecho com ação.", "Regra do professor: 1 ideia central por fala. O resto serve a ela.", "Seu diferencial (clima/extensão/gestão): você tem campo, impacto social e dados. Isso é material narrativo forte."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Escreva uma frase de ideia central e repita 2–3x na palestra.", "Use 1 exemplo real do Pantanal (cena) para dar chão aos dados.", "Diga logo por que isso importa para pessoas (vida real)."], "dont": ["Não abra com currículo/agradecimentos longos.", "Não despeje resultados sem explicar a mensagem.", "Não confunda tema (“clima”) com mensagem (“decisão X salva Y”)."]}, "templates": [{"name": "Ideia central (12–15 palavras)", "text": "Minha ideia central é: ________ (verbo forte) ________ para ________ (impacto)."}, {"name": "Mapa em 3 passos (30s)", "text": "Hoje eu vou te mostrar: (1) ________, (2) ________, (3) ________. No final, você vai conseguir ________."}], "tasks": ["Escreva sua ideia central (12–15 palavras).", "Escolha 1 cena real (campo/extensão) que ilustra a tensão do tema.", "Escreva um mapa em 3 passos (30–40s)."], "theory": ["Tema é o território da conversa; mensagem é aquilo que você quer que alguém compreenda ao sair. “Água no Pantanal” é um tema. Uma mensagem possível precisa dizer algo específico sobre esse tema, sustentado pelo material que você tem. Antes de abrir o PowerPoint, escreva: quem me escuta, qual pergunta essa pessoa tem e que resposta posso defender. Se a resposta exigir muitas ressalvas, mantenha as ressalvas: simplificar a linguagem não autoriza simplificar a evidência.", "Uma estrutura útil começa numa situação reconhecível, apresenta uma pergunta, organiza as evidências e termina numa consequência. Nem toda pesquisa tem uma virada dramática. Resultados inconclusivos também merecem uma narrativa clara: o que foi testado, o que permanece incerto e por que o próximo passo importa. A história deve ajudar a compreender o estudo, sem fazer o estudo parecer mais conclusivo.", "Teste a mensagem com alguém: apresente durante um minuto e peça que a pessoa repita a ideia principal. Não pergunte apenas se gostou. Compare o que ela entendeu com o que você pretendia. Se houver diferença, ajuste o caminho antes de acrescentar novos slides. A meta de uma frase curta é um exercício de foco, não uma regra universal de número de palavras."], "example": {"before": "Vou falar sobre rios, clima, incêndios e biodiversidade.", "after": "Quero mostrar qual pergunta nossos dados respondem sobre este rio — e qual ainda está aberta.", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Escreva seu tema em uma linha.", "Escreva três mensagens possíveis, sem acrescentar fatos novos.", "Escolha a que seus dados sustentam melhor e apresente em 60 segundos.", "Peça a alguém para repetir a ideia; registre a diferença."], "check": {"question": "Qual frase descreve uma mensagem central?", "options": ["Uma lista dos assuntos do trabalho.", "Uma afirmação específica que a apresentação consegue sustentar.", "Um título com palavras difíceis."], "correct": 1, "feedback": "A mensagem é a compreensão que você quer deixar; os assuntos são meios para construí-la."}, "rubric": ["A mensagem tem um verbo e um sentido claro.", "As evidências disponíveis sustentam a frase.", "Um ouvinte consegue repeti-la com suas palavras."], "module": "Fundamentos", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L2", "title": "Aberturas que criam atenção", "minutes": 60, "outcome": "Criar 3 aberturas (acadêmico / gestor / extensão) e escolher a melhor.", "study": ["Abertura tem 3 funções: (1) atenção, (2) promessa de valor, (3) direção (mapa).", "Erro acadêmico clássico: contexto longo antes de dizer o ponto. Isso mata o interesse.", "Gestor/policy maker precisa sentir: ‘qual decisão está na mesa?’ antes do dado.", "Extensão precisa sentir: ‘isso toca a vida real’. Uma cena curta resolve.", "Meta: 25–35 segundos. Abertura boa é curta e assertiva.", "Você (perfil professor + liderança): use autoridade pela clareza, não pela pose."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Comece com pergunta real (decisão).", "Prometa valor: ‘em 5 min você entende X’.", "Dê o mapa: 3 pontos, simples."], "dont": ["Não comece com ‘vou falar sobre…’ sem tensão.", "Não leia slide na abertura.", "Não conte história longa antes do ponto."]}, "templates": [{"name": "Abertura acadêmica (mapa)", "text": "Hoje eu vou responder: ________. Em 3 passos: (1) ___, (2) ___, (3) ___. No final: ___ + próximo passo ___."}, {"name": "Abertura gestor (risco→ação)", "text": "A decisão aqui é: ________. Se não, o risco é: ________. Em 5 min: evidência → impacto → ação em 90 dias."}, {"name": "Abertura extensão (cena)", "text": "Cena real (30s): ________. Isso mostra por que ________ importa. No final, 1 ação simples: ________."}], "tasks": ["Escreva 3 aberturas (acadêmico/gestor/extensão).", "Leia em voz alta e corte 20% sem perder sentido.", "Escolha 1 e refine para 25–35s."], "theory": ["A abertura estabelece um acordo com o público. Ela sinaliza o assunto, o motivo para escutar e a direção da conversa. Uma pergunta relevante, uma observação de campo realmente vivida ou uma comparação documentada pode cumprir esse papel. Escolha um único recurso. Tentar começar ao mesmo tempo com uma piada, uma estatística, uma biografia e uma história costuma dispersar o foco.", "Uma cena deve ser concreta e verificável: onde ocorreu, o que você observou e qual pergunta ela despertou. Não crie falas de moradores, pacientes ou estudantes para dar emoção. Quando usar uma situação inventada para ensinar, apresente-a como hipótese. Uma experiência individual ilustra uma questão; não representa automaticamente toda uma população.", "Depois do início, faça uma ponte curta para o objetivo: “Essa observação nos levou a investigar...” ou “A decisão que precisamos discutir é...”. Ensaiar os primeiros trinta segundos ajuda a começar com direção. Se precisar cumprimentar autoridades, faça-o com respeito e concisão. O tempo da abertura depende da duração total e do contexto; não há uma medida mágica."], "example": {"before": "Bom dia. Meu currículo é longo e primeiro vou ler todos os objetivos.", "after": "Bom dia. Que pergunta sobre este problema nossos dados conseguem responder? É isso que vamos examinar.", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Escreva uma abertura por pergunta, outra por cena real e outra por evidência.", "Leia as três em voz alta, marcando o tempo.", "Escolha a mais pertinente ao público, não a mais dramática.", "Corte informações que não ajudam a chegar à pergunta central."], "check": {"question": "Você precisa de uma cena para abrir a palestra, mas não viveu o episódio. O que fazer?", "options": ["Inventar um depoimento plausível.", "Apresentar a situação explicitamente como hipotética ou escolher outro recurso.", "Atribuir a cena a uma comunidade sem nome."], "correct": 1, "feedback": "Uma situação hipotética pode ensinar, desde que não seja apresentada como relato real."}, "rubric": ["A abertura conecta-se ao tema.", "A promessa pode ser cumprida.", "Cenas e dados têm origem identificável."], "module": "Fundamentos", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L3", "title": "Objetivo, público e ação possível", "minutes": 60, "outcome": "Definir objetivo (verbo), resultado mensurável e CTA (chamada final).", "study": ["Objetivo precisa de verbo forte: ensinar, convencer, mobilizar, destravar, fazer decidir.", "Resultado esperado deve ser mensurável: ‘ao final, você consegue…’.", "CTA é o que acontece depois, com prazo: ‘nos próximos 30 dias…’.", "Para você: uma pesquisa vira 3 versões: aluno (aprender), gestor (decidir), sociedade (engajar).", "Você fica ‘influente’ quando entrega clareza + próximo passo.", "O segredo: menos objetivos, mais precisão."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Escreva objetivo + resultado + CTA em 3 linhas.", "Inclua prazo e responsável no CTA (especialmente para gestores).", "Fale como decisão e não como ‘tema’."], "dont": ["Evite ‘conscientizar’ como objetivo (vago).", "Não termine sem dizer próximo passo.", "Não tente fazer 4 objetivos numa fala."]}, "templates": [{"name": "Objetivo / Resultado / CTA (pronto)", "text": "Objetivo: fazer o público ________.\nResultado: ao final, eles conseguem ________.\nCTA: eu quero que eles ________ até ________."}, {"name": "CTA gestor (90 dias)", "text": "Em 90 dias: (1) ________, (2) ________, (3) ________. Indicador de sucesso: ________."}], "tasks": ["Escolha um tema seu (ex: restauração e saúde humana).", "Preencha Objetivo/Resultado/CTA em 3 versões: aluno/gestor/extensão.", "Escolha a versão ‘gestor’ e refine para 2 frases."], "theory": ["Comece pela mudança que cabe na duração da fala. Em dez minutos talvez seja possível explicar uma diferença, apresentar uma alternativa ou ajudar alguém a formular uma pergunta melhor. Resolver um problema amplo ou mudar sozinho o comportamento de uma comunidade é uma promessa maior do que uma palestra pode garantir. Defina um resultado observável: o ouvinte consegue comparar, explicar, identificar ou decidir algo?", "A ação final precisa respeitar a autonomia do público e suas condições reais. “Façam alguma coisa” deixa tudo em aberto. Uma orientação mais útil identifica uma ação, quem pode realizá-la e o que seria necessário. Uma recomendação de política pública deve vir acompanhada de condições e limites; não transforme uma preferência do palestrante em conclusão científica.", "Faça uma ficha do público: conhecimento prévio, responsabilidades, dúvidas, linguagem e decisões sob seu alcance. Essas hipóteses devem ser confirmadas com quem organiza o evento ou com perguntas à própria audiência. Adaptação não significa dizer o que as pessoas querem ouvir. Significa tornar a mesma evidência compreensível para pessoas com experiências diferentes."], "example": {"before": "Meu objetivo é conscientizar todo mundo.", "after": "Ao final, o público deve conseguir distinguir observação, interpretação e recomendação.", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Defina um público específico.", "Escreva um objetivo com verbo observável.", "Escolha uma ação viável ou uma pergunta que o público possa levar adiante.", "Liste duas barreiras que podem impedir essa ação."], "check": {"question": "Qual objetivo é mais verificável?", "options": ["Inspirar profundamente todos os participantes.", "Fazer o participante distinguir dois conceitos ao final.", "Mudar definitivamente toda a comunidade."], "correct": 1, "feedback": "Um objetivo observável permite conferir se houve compreensão, sem prometer efeitos que a fala não controla."}, "rubric": ["O objetivo cabe no tempo disponível.", "A ação está ao alcance do público.", "A proposta explicita condições e limites."], "module": "Fundamentos", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L4", "title": "Estrutura: pergunta, evidência, consequência", "minutes": 60, "outcome": "Montar roteiro de 6–8 min em 3 blocos com transições.", "study": ["Estrutura segura: (1) o que está acontecendo, (2) por que importa, (3) o que fazer.", "Cada bloco termina com ponte (1 frase que leva ao próximo).", "1 evidência por bloco. Não é revisão bibliográfica oral.", "Para clima/saúde: o bloco 2 precisa ter impacto humano e custo de não agir.", "Você quer uma espinha dorsal repetível para qualquer palestra.", "Roteiro bom é ‘andável’: você consegue falar sem ler."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Dê títulos para cada bloco em 1 frase.", "Escreva 2 pontes curtas (transições).", "Corte tudo que não serve a um dos blocos."], "dont": ["Não faça vai-e-volta de assuntos.", "Não detalhe método no meio do talk (só o necessário).", "Não use jargão sem traduzir."]}, "templates": [{"name": "Roteiro 3 blocos (6–8 min)", "text": "Bloco 1 (o que acontece): ________ (1 evidência)\nPonte: “O ponto é ________.”\nBloco 2 (por que importa): ________ (impacto)\nPonte: “Então precisamos ________.”\nBloco 3 (o que fazer): 3 ações: (1) ___ (2) ___ (3) ___."}], "tasks": ["Monte roteiro 3 blocos + 2 pontes.", "Leia cronometrando 6–8 min.", "Marque 2 trechos confusos e reescreva."], "theory": ["Organizar uma palestra é decidir a ordem em que a compreensão será construída. Comece por uma pergunta clara. Em seguida, apresente apenas o contexto necessário para entendê-la. Organize o desenvolvimento em poucos blocos, cada um com uma função: definir o problema, examinar a evidência, discutir implicações. A quantidade de blocos depende do tempo e da complexidade, não de uma fórmula obrigatória.", "Dentro de cada bloco, use uma afirmação que você possa sustentar, apresente sua base e explique o significado. Se o dado não permite responder à pergunta, diga isso. Uma transição deve mostrar por que o próximo assunto é necessário: “Agora que sabemos como medimos, podemos comparar...” é mais informativo que apenas anunciar “próximo slide”.", "Faça uma versão de emergência. Se o tempo cair pela metade, quais peças precisam permanecer para que a conclusão não perca sustentação? Corte exemplos secundários antes de cortar a evidência central ou os limites do estudo. Um roteiro modular permite adaptar a fala sem acelerar tanto que o público deixe de acompanhar."], "example": {"before": "Introdução, revisão, método, resultados... sem uma pergunta que una tudo.", "after": "Que pergunta investigamos? Como avaliamos? O que encontramos? O que isso permite dizer?", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Escreva a pergunta central.", "Distribua os slides em três ou quatro blocos com funções claras.", "Escreva uma transição entre cada par de blocos.", "Prepare uma versão com metade do tempo."], "check": {"question": "Se o tempo da palestra diminuir, qual ajuste preserva melhor o rigor?", "options": ["Eliminar todas as limitações.", "Acelerar e ler todos os slides.", "Retirar exemplos secundários, mantendo evidências e limites essenciais."], "correct": 2, "feedback": "A versão curta precisa continuar sustentando a conclusão."}, "rubric": ["Cada bloco responde a uma necessidade.", "As transições explicam a sequência.", "Existe uma versão curta coerente."], "module": "Fundamentos", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L5", "title": "Um final que permanece", "minutes": 60, "outcome": "Criar 3 fechamentos e escolher 1 memorável com CTA.", "study": ["O fechamento decide se você será lembrado.", "3 formatos: pergunta forte (decisão), convite prático (prazo), frase-marca (identidade).", "Seu fecho precisa reconectar com a ideia central (Aula 1).", "Para política pública: fecho tem que ser executável (quem faz + quando).", "Você quer um fecho que repete em qualquer palestra do tema."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Feche com 1 frase curta + CTA.", "Volte na ideia central do começo.", "Finalize com calma (sem acelerar)."], "dont": ["Não termine com ‘é isso’ sem mensagem.", "Não abra assunto novo no final.", "Não peça desculpa por tempo/conteúdo."]}, "templates": [{"name": "Fecho pergunta", "text": "“Se você tivesse que decidir hoje, escolheria ________ ou ________?”"}, {"name": "Fecho convite (30 dias)", "text": "“Nos próximos 30 dias, vamos ________. Eu me comprometo com ________.”"}, {"name": "Fecho frase-marca", "text": "“No Pantanal, ________. E é por isso que ________.”"}], "tasks": ["Escreva 3 fechamentos (um de cada tipo).", "Escolha o mais forte e refine para 20–25s.", "Cole aqui sua versão final na Entrega."], "theory": ["O encerramento reúne o percurso. Retome a pergunta inicial e diga qual resposta o material permite oferecer. Se a abertura trouxe uma cena, você pode voltar a ela mostrando o que agora ficou mais claro. Essa retomada produz unidade sem exigir um efeito teatral. Evite acrescentar uma descoberta importante nos últimos segundos: ela não terá tempo de ser examinada.", "Separe três movimentos: síntese, limite e próximo passo. A síntese é a mensagem principal. O limite informa o que continua incerto. O próximo passo pode ser uma ação, uma decisão ou uma nova pergunta. Uma fala acadêmica pode terminar com uma contribuição modesta e sólida; não precisa prometer uma solução definitiva.", "Escreva a última frase e ensaie a pausa que vem depois. O público precisa perceber que você concluiu. Em eventos com perguntas, anuncie a transição e mantenha uma tela útil, com a mensagem central e um contato autorizado. Agradecimentos são bem-vindos, mas não precisam substituir a conclusão. Deixe o material de apoio disponível quando isso for apropriado."], "example": {"before": "É isso. Acho que falei tudo. Obrigado.", "after": "A resposta que conseguimos sustentar é esta: [mensagem]. O limite é [limite]. O próximo passo é [ação].", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Escreva síntese, limite e próximo passo.", "Prepare um encerramento de 40 segundos.", "Verifique se ele responde à abertura.", "Grave duas versões e escolha a mais clara."], "check": {"question": "O que deve aparecer no encerramento?", "options": ["Um resultado central inédito, sem explicação.", "A síntese sustentada e o próximo passo possível.", "Uma nova revisão bibliográfica completa."], "correct": 1, "feedback": "O fechamento consolida o que foi construído ao longo da fala."}, "rubric": ["A conclusão responde à pergunta inicial.", "Nenhum limite essencial foi escondido.", "A última frase tem direção clara."], "module": "Fundamentos", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L6", "title": "Voz, ritmo e pausas", "minutes": 60, "outcome": "Controlar ritmo e pausa para soar seguro sem ‘forçar’ a voz.", "study": ["Voz não é volume; é controle.", "Pausa cria autoridade: você mostra que sabe onde está indo.", "Ritmo bom alterna: frase curta (impacto) + frase média (explica).", "Ênfase: escolha 1 palavra por frase para marcar (não tudo).", "Exercício-chave: ‘fala com freio’ — você corta 15% da velocidade."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Use pausa antes da frase mais importante.", "Finalize frase no fim (não deixe cair).", "Respire antes do ponto-chave."], "dont": ["Não acelere para ‘terminar logo’.", "Não use muletas (‘né’, ‘tipo’) sem perceber.", "Não fale o tempo todo sem pausa."]}, "templates": [{"name": "Frase de impacto (com pausa)", "text": "[Pausa] A verdade é: ________. [Pausa] E isso muda ________."}], "tasks": ["Leia o template 10x com pausa e grave 30s (opcional).", "Conte quantos ‘né/tipo’ aparecem. Regrave reduzindo pela metade.", "Escreva 3 frases de impacto sobre seu tema."], "theory": ["A voz organiza o sentido. Uma pausa pode separar duas ideias, permitir a leitura de uma figura ou destacar uma pergunta. Experimente marcar o roteiro com barras: uma barra para uma pequena separação e duas para uma pausa de reflexão. Essas marcas são apoio ao ensaio, não uma partitura que você precisa seguir mecanicamente.", "Varie o ritmo conforme a dificuldade do trecho. Uma descrição simples pode fluir mais rapidamente; um conceito novo, uma unidade ou uma limitação exige espaço. Não há uma velocidade universal adequada a todas as pessoas e contextos. Grave um trecho, observe se as palavras são compreensíveis e peça retorno ao público pretendido. A contagem de palavras por minuto só tem sentido quando texto e duração correspondem à mesma fala.", "Fale numa altura confortável, use o microfone quando disponível e faça testes antes. Articule as terminações sem caricaturar a pronúncia. Não tente forçar um timbre grave para parecer mais confiável. Respeite seu jeito de falar, seu sotaque e suas necessidades de acessibilidade; o objetivo é compreensão. Interrompa exercícios que provoquem desconforto e procure orientação profissional quando necessário."], "example": {"before": "Ler todas as frases na mesma velocidade e sem respirar entre ideias.", "after": "Marcar uma pausa antes da conclusão e dar tempo para o público ler a unidade do gráfico.", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Escolha um texto de 120 a 180 palavras.", "Marque três pausas de sentido.", "Grave uma versão e ouça a inteligibilidade.", "Repita alterando apenas uma característica, como o ritmo."], "check": {"question": "O que uma contagem de palavras por minuto mostra?", "options": ["A qualidade total da palestra.", "Uma medida de ritmo quando texto e duração correspondem.", "O nível de confiança psicológica do palestrante."], "correct": 1, "feedback": "Ritmo é apenas uma dimensão; clareza, contexto e compreensão também importam."}, "rubric": ["As palavras são compreensíveis.", "As pausas acompanham o sentido.", "O ritmo permite acompanhar trechos difíceis."], "module": "Voz, presença e recursos", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L7", "title": "Presença, corpo e acessibilidade", "minutes": 60, "outcome": "Reduzir nervosismo visível e ganhar presença com 3 regras simples.", "study": ["Presença é estabilidade + intenção. Não é ‘performance’.", "Regra 1: pé firme, ombro relaxado, queixo neutro.", "Regra 2: mãos servem ao raciocínio (apontar, comparar, enumerar).", "Regra 3: olhar ‘varre’ o público em blocos (3–4 pontos).", "Se você treme: diminua a velocidade e aumente a pausa."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Faça gesto apenas quando ajuda entendimento.", "Olhe quando falar a frase mais importante.", "Use enumeração com dedos (1,2,3) com calma."], "dont": ["Não ‘dance’ nem balance sem motivo.", "Não esconda as mãos o tempo todo.", "Não olhe só para o slide."]}, "templates": [{"name": "Gestos por função", "text": "Quando eu comparar duas coisas, eu abro as mãos (A vs B).\nQuando eu listar, eu marco (1)(2)(3).\nQuando eu concluir, eu paro e faço pausa."}], "tasks": ["Faça 1 minuto em pé: 3 pontos (1)(2)(3) com gesto de enumeração.", "Grave (opcional) e marque 1 ajuste corporal.", "Anote 1 ‘tic’ (mexer pé, balançar) e reduza 50%."], "theory": ["Presença é disponibilidade para a comunicação, não um modelo único de postura. Uma pessoa pode apresentar sentada, em pé ou com apoio e ainda assim estabelecer excelente contato com a audiência. Organize seu corpo e o espaço de modo confortável e compatível com seus recursos. Não use gestos ou contato visual como diagnóstico da personalidade de ninguém.", "Direcione a atenção para a mensagem: evite cobrir a projeção, mantenha distância adequada do microfone e deixe materiais à mão. Gestos podem indicar uma comparação, uma sequência ou uma dimensão. Eles ajudam quando acompanham o sentido; coreografias repetidas podem distrair. Olhar para diferentes regiões da sala é uma opção, mas não uma obrigação para quem encontra dificuldade nisso.", "Acessibilidade faz parte do preparo. Descreva oralmente o que importa numa imagem, use contraste legível e não dependa exclusivamente da cor para distinguir categorias. Em ambientes on-line, teste enquadramento, luz e áudio. Combine com a organização recursos como legendas e interpretação quando necessários. O melhor critério de presença é se o público consegue acompanhar o que você comunica."], "example": {"before": "Como vocês podem ver nesta linha vermelha...", "after": "A série identificada como “grupo A” sobe neste intervalo; vou explicar a comparação e sua unidade.", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Grave um minuto numa posição confortável.", "Confira microfone, enquadramento e obstáculos.", "Descreva uma figura sem depender de “aqui” e “ali”.", "Peça a alguém que escute sem olhar a tela."], "check": {"question": "Qual prática melhora a acessibilidade?", "options": ["Usar apenas cores para identificar grupos.", "Exigir contato visual contínuo de qualquer palestrante.", "Nomear os grupos e descrever oralmente a informação essencial."], "correct": 2, "feedback": "Descrição e identificação explícita ajudam diferentes públicos a acompanhar."}, "rubric": ["A posição é confortável e funcional.", "Gestos e deslocamentos não ocultam a informação.", "O conteúdo visual essencial é descrito."], "module": "Voz, presença e recursos", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L8", "title": "Slides que trabalham a favor da fala", "minutes": 60, "outcome": "Transformar slides em apoio visual: 1 ideia por slide, 6 palavras ou menos.", "study": ["Slide não é roteiro; é apoio visual.", "Regra de ouro: 1 ideia por slide. O resto vira fala.", "Texto demais cria ‘leitura simultânea’ e derruba atenção.", "Seu público (gestor/policy): quer síntese + decisão, não ‘tabela infinita’.", "Use gráficos com frase-título: ‘O pico de X ocorreu em Y — por causa de Z’."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Escreva o título do slide como conclusão.", "Use 1 gráfico por slide.", "Deixe espaço em branco (respira)."], "dont": ["Não copie parágrafo para slide.", "Não use 10 cores sem sentido.", "Não deixe eixo/legenda ilegíveis."]}, "templates": [{"name": "Título-conclusão", "text": "Em vez de: ‘Resultados’\nUse: ‘A restauração reduz risco de mortalidade em ondas de calor’"}], "tasks": ["Pegue 1 slide seu e corte 70% do texto.", "Reescreva o título como conclusão.", "Cole a versão final na Entrega (texto)."], "theory": ["Um slide é uma ferramenta de atenção. Pergunte o que o público precisa enxergar naquele momento. Se a resposta for uma tendência, priorize o gráfico; se for uma comparação, organize os elementos lado a lado; se for uma ideia, uma frase pode bastar. O título pode antecipar a leitura desejada, desde que a figura realmente a sustente.", "Faça uma revisão de números: unidade, população, lugar, período, denominador e fonte. Comparações precisam de bases compatíveis. Uma diferença entre barras não prova por si só uma diferença estatística; uma associação não demonstra causalidade. Barras de incerteza precisam de legenda, porque podem representar quantidades diferentes. Se não souber o que uma marca representa, confira o arquivo original antes de interpretá-la.", "Reduza texto que você pretende falar e mantenha na tela o que o ouvinte precisa consultar. Não existe um número fixo de palavras que resolva qualquer slide. Tamanho da sala, projeção e complexidade importam. Teste a leitura em uma tela pequena e ensaie com a versão efetivamente usada. Slides compostos apenas por imagem podem exigir uma descrição manual no estúdio."], "example": {"before": "Um gráfico sem unidade e com título “Resultados”.", "after": "Um gráfico com grupos identificados, unidade, período, fonte e um título que não excede a evidência.", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Importe uma apresentação no estúdio.", "Escolha um slide com texto e um com gráfico.", "Revise a mensagem, a referência e a unidade.", "Diga em voz alta o que o público deve observar primeiro."], "check": {"question": "Duas séries variam juntas num gráfico. O que isso demonstra sozinho?", "options": ["Uma relação causal comprovada.", "Uma associação visual que precisa de análise e contexto.", "Que uma série sempre prevê perfeitamente a outra."], "correct": 1, "feedback": "A figura pode sugerir associação; causalidade exige evidência adicional."}, "rubric": ["O slide tem uma função clara.", "Números têm contexto e fonte.", "A fala orienta a leitura sem exagerar conclusões."], "module": "Voz, presença e recursos", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L9", "title": "Exemplos reais e analogias honestas", "minutes": 60, "outcome": "Criar 2 exemplos fortes (cena + dado) para seu tema principal.", "study": ["Memória vem de: cena concreta + número simples + consequência humana.", "Cena: 10–20s. Dado: 1 linha. Consequência: 1 frase.", "Para clima: sempre responda ‘e daí?’ — impacto, custo, decisão.", "Exemplo ruim: abstrato e longo. Exemplo bom: concreto e curto.", "Você tem material: campo no Pantanal, extensão, saúde, políticas públicas."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Use exemplos com lugar/tempo (‘em Cáceres, 2023…’).", "Use número redondo (aprox.) quando possível.", "Diga a consequência em 1 frase."], "dont": ["Não use 5 números seguidos.", "Não conte caso sem ponto.", "Não descreva método inteiro como exemplo."]}, "templates": [{"name": "Exemplo cena+dado+consequência", "text": "Cena (15s): ________.\nDado (1 linha): ________.\nConsequência (1 frase): ________.\nPonte: “Isso nos leva a ________.”"}], "tasks": ["Crie 2 exemplos completos com o template.", "Escolha o melhor e encaixe no bloco 2 do seu roteiro (Aula 4).", "Cole na Entrega."], "theory": ["Um exemplo aproxima uma ideia da experiência. Para usá-lo bem, diga qual aspecto ele ilustra. Um caso de campo pode tornar uma pergunta concreta, mas não substitui uma amostra. Se a observação veio de você, informe as condições. Se veio de outra pessoa, respeite autoria, privacidade e autorização. Uma frase entre aspas precisa corresponder a uma fala real, não a uma reconstrução conveniente.", "Analogias comparam aspectos de duas situações. Dizer que um sistema funciona “como uma esponja” pode ajudar a imaginar armazenamento, mas a comparação não descreve todos os processos físicos. Explicite onde a analogia funciona e onde deixa de funcionar. Quando o público já compreendeu o conceito, volte à descrição científica.", "Número, cena e consequência só devem ser conectados quando a relação tiver sustentação. Não acrescente um custo financeiro, uma doença ou um impacto social apenas porque isso tornaria o exemplo emocionante. Se a consequência for uma hipótese, marque-a como hipótese e diga que informação seria necessária para examiná-la."], "example": {"before": "Uma história isolada prova que toda a região vive a mesma situação.", "after": "Este caso ilustra a pergunta; para falar da região inteira, precisamos de uma base representativa.", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Selecione um episódio real e anote sua origem.", "Explique em uma frase o que ele ilustra.", "Escreva o que não pode ser generalizado a partir dele.", "Crie uma analogia e registre o limite da comparação."], "check": {"question": "Um relato individual pode ser usado para quê?", "options": ["Estimar automaticamente a frequência regional.", "Ilustrar uma questão, com limites explícitos.", "Substituir qualquer análise de dados."], "correct": 1, "feedback": "O caso ajuda a entender a pergunta; generalização exige desenho e evidência apropriados."}, "rubric": ["O exemplo tem origem identificada.", "A analogia tem limite declarado.", "A consequência não foi inventada."], "module": "Voz, presença e recursos", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L10", "title": "Diagnóstico e feedback útil", "minutes": 60, "outcome": "Identificar 5 erros pessoais e montar um plano de correção de 7 dias.", "study": ["Você não precisa virar outra pessoa. Você precisa cortar ruídos.", "5 erros comuns: contexto longo, frases longas, sem pausa, sem CTA, slide-texto.", "Correção rápida: 1 erro por semana, não tudo de uma vez.", "Aula prática: você vai criar seu ‘manual pessoal’ de oratória.", "Professor bom é quem se auto-observa com gentileza e método."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Escolha 1 erro para corrigir nesta semana.", "Crie um lembrete antes da palestra.", "Peça 1 feedback específico (clareza/ritmo/CTA)."], "dont": ["Não tente corrigir 10 coisas de uma vez.", "Não se ataque — foque em ajuste.", "Não ignore gravação curta (30s)."]}, "templates": [{"name": "Plano de 7 dias", "text": "Erro principal: ________.\nSinal de alerta: ________.\nRegra simples: ________.\nTreino diário (3 min): ________.\nMeta em 7 dias: ________."}], "tasks": ["Marque seus 5 erros mais prováveis (escreva).", "Escolha 1 para a semana e preencha o plano de 7 dias.", "Cole a versão final na Entrega."], "theory": ["Melhorar uma apresentação começa por observar comportamentos específicos. “Sou ruim falando” é uma avaliação ampla e pouco acionável. “Introduzi três conceitos antes de explicar o primeiro” aponta para uma mudança concreta. Use gravações curtas e examine uma dimensão por vez: clareza, organização, ritmo ou leitura dos gráficos.", "Peça feedback em perguntas abertas e verificáveis. Qual foi a ideia principal? Em que momento ficou difícil acompanhar? Que informação faltou para aceitar a conclusão? Evite conduzir o ouvinte à resposta desejada. Gostar de uma apresentação não significa necessariamente compreendê-la, e discordar da conclusão não significa que ela foi mal comunicada.", "Escolha um ajuste para a próxima rodada. Faça uma nova gravação com o mesmo objetivo e compare os resultados. Uma rubrica ajuda a manter critérios constantes, mas uma autoavaliação não é uma medida objetiva de competência. Registre quem avaliou, qual trecho observou e em que contexto. Use a nota para orientar prática, não para rotular a pessoa."], "example": {"before": "Você precisa ter mais carisma.", "after": "Na explicação do gráfico, diga primeiro qual grupo estamos comparando e em qual unidade.", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Grave dois minutos de uma fala.", "Escolha uma dificuldade observável.", "Peça retorno usando três perguntas específicas.", "Repita o trecho com uma única mudança."], "check": {"question": "Qual feedback é mais acionável?", "options": ["Você não nasceu para isso.", "Seja mais interessante.", "Defina a sigla antes de usá-la no segundo slide."], "correct": 2, "feedback": "Uma observação específica permite testar uma melhoria."}, "rubric": ["O feedback descreve um comportamento.", "O ajuste é praticável.", "A comparação usa o mesmo critério."], "module": "Voz, presença e recursos", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L11", "title": "Tensão narrativa sem exagero", "minutes": 60, "outcome": "Transformar seu tema em narrativa: tensão → virada → caminho.", "study": ["Sem tensão não existe história: existe exposição.", "Tensão = o que está em risco (humano, econômico, ecológico).", "Virada = o momento de insight: ‘o que ninguém está vendo’.", "Caminho = 3 ações possíveis (o público sai com direção).", "Você vai usar isso em clima, restauração, saúde, extensão."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Declare o risco em 1 frase curta.", "Mostre a virada com 1 exemplo claro.", "Ofereça 3 caminhos, não 20."], "dont": ["Não esconda o risco até o final.", "Não complique a virada com jargão.", "Não entregue solução sem mostrar tensão."]}, "templates": [{"name": "Tensão → Virada → Caminho", "text": "Tensão (risco): ________.\nVirada (insight): ________.\nCaminho (3 ações): (1) ___ (2) ___ (3) ___."}], "tasks": ["Escreva tensão/virada/caminho do seu tema principal.", "Leia em voz alta e corte 20%.", "Cole na Entrega."], "theory": ["Tensão é a distância entre uma pergunta importante e uma resposta ainda incompleta. Ela pode nascer de uma decisão difícil, de resultados que divergem de uma expectativa ou de uma limitação metodológica. Não é necessário transformar qualquer pesquisa numa emergência. O tamanho da preocupação deve acompanhar a evidência disponível.", "Uma virada é uma mudança de compreensão. Mostre primeiro qual era a expectativa e de onde ela veio; depois, explique o resultado que exigiu uma revisão. Se a expectativa foi apenas sua, não a atribua a toda a comunidade científica. Se o resultado for exploratório, conserve essa condição na narrativa.", "Evite suspender informação essencial apenas para surpreender. O público precisa de condições para interpretar o que vê. Uma narrativa científica pode mostrar uma incerteza que permaneceu, uma hipótese descartada ou um método que precisou mudar. Essas passagens ajudam a comunicar o processo de investigação com honestidade."], "example": {"before": "Ninguém sabia de nada até nossa descoberta definitiva.", "after": "Partimos desta hipótese. Os resultados nos levaram a revisá-la, dentro destes limites.", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Identifique uma pergunta que ainda produz dúvida.", "Descreva a expectativa inicial e sua origem.", "Escreva o que seus resultados mudaram de fato.", "Releia e elimine afirmações absolutas sem suporte."], "check": {"question": "Como criar tensão narrativa com rigor?", "options": ["Ampliar artificialmente o risco.", "Apresentar uma pergunta real cuja resposta importa.", "Esconder limitações até terminar a sessão de perguntas."], "correct": 1, "feedback": "A relevância da pergunta pode sustentar o interesse sem distorcer o estudo."}, "rubric": ["A tensão vem de um problema real.", "A virada corresponde aos resultados.", "O grau de certeza foi preservado."], "module": "Narrativa e públicos", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L12", "title": "Storyboard e gestão do tempo", "minutes": 60, "outcome": "Montar storyboard completo e repetível para seu talk principal.", "study": ["Storyboard = sequência de cenas/pontos (não texto corrido).", "Você vai montar: abertura → bloco 1 → bloco 2 → bloco 3 → fecho.", "Cada parte precisa de 1 frase de função: o que esta parte faz?", "Talk repetível = você consegue dar em qualquer lugar mudando só exemplo/dado.", "Seu alvo: falar com clareza para público misto (academia + gestão + sociedade)."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Use post-its (mentalmente) — 8 a 12 cartões.", "Cada cartão tem 1 frase.", "Tenha 2 exemplos prontos (um curto, um forte)."], "dont": ["Não escreva texto inteiro para decorar.", "Não tenha 40 cartões.", "Não pule direto para slide sem storyboard."]}, "templates": [{"name": "Storyboard (cartões)", "text": "Cartão 1 (abertura): ________\n2 (bloco 1): ________\n3 (ponte): ________\n4 (bloco 2): ________\n5 (ponte): ________\n6 (bloco 3): ________\n7 (fecho): ________\n8 (CTA): ________"}], "tasks": ["Monte storyboard com 8–12 cartões (frases curtas).", "Fale 5 minutos olhando só para os cartões (sem ler texto).", "Cole storyboard final na Entrega."], "theory": ["Antes de aperfeiçoar a aparência dos slides, organize cartões com a função de cada trecho. Um cartão pode dizer “formular a pergunta”, outro “mostrar a comparação” e outro “explicar a limitação”. Essa visão permite enxergar repetições e saltos lógicos. A sequência de arquivos no PowerPoint não precisa ser a sequência definitiva da apresentação.", "Distribua o tempo conforme a importância e a dificuldade. Slides não exigem durações iguais: um agradecimento pode ser breve e um gráfico complexo pode precisar de mais tempo. Reserve espaço para pausas e perguntas, se o formato permitir. A divisão automática do estúdio é apenas um ponto inicial; ajuste-a após o ensaio.", "Prepare pontos de corte. Marque exemplos opcionais que podem sair sem alterar o argumento. Conheça a mensagem de cada bloco para se recuperar se esquecer uma frase ou precisar pular um slide. O objetivo é dominar o percurso, não decorar palavra por palavra. Registre o tempo real de uma rodada completa para comparar com o planejado."], "example": {"before": "Tenho vinte slides, então cada um precisa de exatamente um minuto.", "after": "O gráfico central precisa de explicação; os slides de transição podem ser mais breves.", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Escreva uma função para cada slide.", "Agrupe os cartões por blocos.", "Marque dois trechos opcionais.", "Ensaie a versão completa e registre o tempo de cada bloco."], "check": {"question": "Como deve ser distribuído o tempo?", "options": ["Sempre igualmente por slide.", "Conforme a função e a complexidade de cada trecho.", "Todo o tempo nos métodos, independentemente do público."], "correct": 1, "feedback": "O ensaio revela quanto cada parte exige para ser compreendida."}, "rubric": ["Os cartões formam um argumento.", "O tempo foi ensaiado.", "Os cortes preservam a conclusão."], "module": "Narrativa e públicos", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L13", "title": "Ciência e decisões públicas", "minutes": 60, "outcome": "Converter pesquisa em decisão: pergunta de decisão, evidência, impacto, ação.", "study": ["Policy não compra ‘tema’. Compra clareza para decidir.", "Pergunta de decisão: ‘o que vocês precisam decidir hoje?’", "Evidência: 1 número ou tendência + confiança (sem jargão excessivo).", "Impacto: custo de não agir e benefício de agir.", "Ação: 3 medidas em 90 dias (responsável + indicador)."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Abra com decisão e risco.", "Mostre 1 gráfico com título-conclusão.", "Feche com ação em 90 dias."], "dont": ["Não entregue método detalhado antes da decisão.", "Não jogue 12 gráficos.", "Não termine sem responsável/indicador."]}, "templates": [{"name": "Modelo policy (5 min)", "text": "Decisão: ________.\nRisco se não agir: ________.\nEvidência (1): ________.\nImpacto humano/econômico: ________.\nAção em 90 dias: (1) ___ (2) ___ (3) ___.\nIndicador: ________."}], "tasks": ["Escolha 1 decisão real (ex: restauração, saúde, fogo).", "Preencha o modelo policy completo.", "Cole na Entrega."], "theory": ["Uma decisão pública envolve evidência, valores, recursos, responsabilidades e incerteza. O papel do pesquisador pode ser esclarecer alternativas e suas consequências, sem apresentar uma escolha política como se fosse a única conclusão científica possível. Identifique quem decide, qual decisão está em discussão e em que prazo.", "Ao apresentar uma recomendação, separe o achado da proposta. “Observamos esta associação” não equivale a “esta intervenção produzirá o efeito desejado”. Explique quais passos conectam os dois enunciados e quais precisam de avaliação. Quando custos ou benefícios não tiverem sido estimados, não invente números. Mostre a lacuna como uma necessidade de informação.", "Prepare uma síntese curta com problema, evidência, limites, opções e próximos passos. Use termos compreensíveis sem esconder as condições do estudo. Pergunte que informação a equipe gestora precisa para agir. Ofereça referências e um modo de acompanhar os resultados caso uma medida seja implementada."], "example": {"before": "A ciência manda executar esta política e não há alternativas.", "after": "Estes resultados ajudam a comparar opções; a escolha também depende de recursos, prioridades e avaliação.", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Escolha uma decisão concreta.", "Separe achado, interpretação e recomendação.", "Liste duas opções e a informação necessária para compará-las.", "Prepare uma fala de três minutos para a equipe responsável."], "check": {"question": "Uma recomendação é automaticamente um resultado científico?", "options": ["Sim, se quem fala é pesquisador.", "Não; a ligação entre resultado e proposta deve ser explicitada.", "Sim, quando aparece num slide com gráfico."], "correct": 1, "feedback": "Recomendações incorporam escolhas e condições além do achado empírico."}, "rubric": ["A decisão está identificada.", "Achado e proposta estão separados.", "As incertezas e condições são explícitas."], "module": "Narrativa e públicos", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L14", "title": "Aula que produz compreensão", "minutes": 60, "outcome": "Transformar uma aula em jornada: pergunta central, exemplos, prática, fecho.", "study": ["Boa aula não é só conteúdo: é organização + prática + sentido.", "Pergunta central: o que o aluno precisa saber fazer ao final?", "Exemplo concreto → conceito → exercício curto → feedback.", "Você mantém rigor, mas entrega em blocos digeríveis.", "Docência de excelência: clareza, ritmo, checagem de entendimento."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Comece com pergunta-problema.", "Faça micro-exercício de 3–5 min.", "Feche recapitulando 1 ideia central."], "dont": ["Não faça 50 min sem interação.", "Não confunda ‘falar muito’ com ‘ensinar’.", "Não finalize sem checar entendimento."]}, "templates": [{"name": "Roteiro de aula (50 min)", "text": "Pergunta central: ________.\nExemplo 1: ________.\nConceito: ________.\nExercício 5 min: ________.\nDiscussão: ________.\nFecho (1 frase): ________."}], "tasks": ["Escolha uma aula real sua e aplique o roteiro.", "Crie 1 exercício de 5 min para a turma.", "Cole o roteiro final na Entrega."], "theory": ["Uma aula precisa oferecer oportunidades para o estudante usar o que acabou de ouvir. Defina uma habilidade ou compreensão central e construa a sequência a partir dela. Um problema concreto pode abrir a aula; a explicação introduz os conceitos necessários; uma tarefa curta permite experimentar; o retorno corrige interpretações.", "Faça perguntas que revelem raciocínio. “Entenderam?” tende a produzir respostas pouco informativas. Peça que alguém explique uma escolha, compare duas interpretações ou identifique um erro num exemplo. Ofereça tempo para pensar e possibilidades diferentes de participação, como escrita individual antes da discussão.", "Ao usar dados reais, informe a origem e o que foi transformado para fins didáticos. Dados fictícios também podem ensinar, desde que estejam rotulados. Encerre retomando o problema inicial e verificando se a turma consegue resolvê-lo melhor. Use o resultado dessa checagem para planejar a próxima aula."], "example": {"before": "Entenderam? Então podemos continuar.", "after": "Qual destas duas interpretações o gráfico sustenta? Explique que informação você usou.", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Defina um objetivo de aprendizagem.", "Crie um problema de abertura.", "Proponha uma tarefa de cinco minutos.", "Escreva o feedback para dois erros prováveis."], "check": {"question": "Qual pergunta verifica melhor a compreensão?", "options": ["Entenderam tudo?", "Gostaram da aula?", "Qual interpretação é sustentada pelos dados, e por quê?"], "correct": 2, "feedback": "Pedir uma justificativa torna o raciocínio visível."}, "rubric": ["O objetivo orienta a atividade.", "Há tempo para pensar e participar.", "O fechamento verifica a aprendizagem."], "module": "Narrativa e públicos", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L15", "title": "Extensão e escuta respeitosa", "minutes": 60, "outcome": "Criar fala de extensão com respeito: cena, sentido, convite, pertença.", "study": ["Extensão é relação: você fala com, não fala sobre.", "Comece com cena real e devolva protagonismo às pessoas.", "Use ‘nós’ com cuidado: pertença sem apagar diversidade.", "Convite simples e realizável (micro-ação).", "Resultado: mobilização por dignidade, não por medo."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Traga cena + respeito + convite.", "Traduza jargão em linguagem cotidiana.", "Feche com 1 ação pequena."], "dont": ["Não trate público como ignorante.", "Não faça terror sem saída.", "Não dê 10 chamadas de uma vez."]}, "templates": [{"name": "Fala de extensão (3 min)", "text": "Cena: ________.\nSentido: por que isso importa: ________.\nConvite: hoje a gente pode ________.\nFecho: ‘se a gente fizer isso, ________.’"}], "tasks": ["Escreva uma fala de extensão de 3 min.", "Refine para linguagem simples (sem jargão).", "Cole na Entrega."], "theory": ["Comunicação com comunidades começa por escutar, não por presumir o que falta às pessoas. Conhecimentos locais, experiências e prioridades podem revelar perguntas que a apresentação original não considerou. Pergunte como o problema aparece na vida cotidiana e quem precisa participar da conversa. Evite tratar a comunidade como um grupo homogêneo.", "Traduza termos sem infantilizar. Uma palavra técnica pode ser apresentada junto com sua definição e um exemplo pertinente. Não substitua precisão por uma metáfora que gere uma compreensão errada. Confirme o entendimento convidando o público a reformular a ideia ou relacioná-la à própria experiência.", "Relatos de pessoas exigem cuidado com identificação e consentimento. Ao comunicar resultados obtidos num território, planeje a devolutiva de forma acessível e útil. Declare o que a pesquisa pode oferecer e o que está fora do seu alcance. Uma atividade de extensão também deve permitir que as perguntas do público alterem a pauta."], "example": {"before": "Eu sei o que esta comunidade precisa aprender.", "after": "Quais questões vocês gostariam que estes dados ajudassem a responder?", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Liste três perguntas de escuta.", "Reescreva um conceito técnico em linguagem acessível.", "Prepare uma explicação sem depender do projetor.", "Defina como registrar e devolver as dúvidas recebidas."], "check": {"question": "O que caracteriza uma boa adaptação para extensão?", "options": ["Retirar todas as incertezas.", "Escutar prioridades e explicar conceitos sem infantilizar.", "Supor que todas as pessoas têm a mesma experiência."], "correct": 1, "feedback": "Adaptação exige diálogo, respeito e preservação do conteúdo."}, "rubric": ["O público pode formular perguntas.", "A linguagem é acessível e respeitosa.", "A devolutiva tem utilidade concreta."], "module": "Narrativa e públicos", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L16", "title": "Improviso com uma estrutura simples", "minutes": 60, "outcome": "Responder sem travar: técnica de 3 passos + ponte.", "study": ["Improviso não é falar qualquer coisa: é responder com estrutura.", "Técnica 3 passos: (1) responda direto, (2) explique 1 evidência, (3) amarre com implicação.", "Ponte: ‘isso nos leva a…’ para voltar ao seu roteiro.", "Você nunca precisa ‘saber tudo’. Precisa ser honesto e claro.", "Treino: respostas de 20–40s."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Responda direto em 1 frase.", "Use 1 evidência, não 10.", "Volte para a mensagem central."], "dont": ["Não comece com ‘depende’ por hábito.", "Não ataque o perguntador.", "Não se perca em tangentes."]}, "templates": [{"name": "Resposta 3 passos (40s)", "text": "Resposta direta: ________.\nEvidência curta: ________.\nImplicação/ponte: ________ (e isso nos leva a…)."}], "tasks": ["Escreva 5 perguntas difíceis que já te fizeram.", "Responda com o template (1 por pergunta).", "Cole a melhor resposta na Entrega."], "theory": ["Improvisar é organizar uma resposta com pouco tempo, não saber tudo instantaneamente. Antes de falar, identifique qual pergunta foi feita. Uma pausa breve pode ajudar a escolher o ponto principal. Se a pergunta for ambígua, peça uma especificação em vez de responder a outra coisa.", "Uma resposta curta pode seguir posição, razão, exemplo e retorno ao ponto. Essa estrutura é uma ferramenta de treino, não uma obrigação. O exemplo deve ser verdadeiro ou explicitamente hipotético. Se você não tiver a informação necessária, delimite o que sabe e o que precisaria consultar.", "Treine com perguntas relacionadas ao seu trabalho e também com situações comuns, como apresentar um projeto a alguém de outra área. Alterne respostas de trinta, sessenta e noventa segundos. Compare o foco entre as versões. Improviso melhora quando você conhece bem suas mensagens, suas evidências e seus limites."], "example": {"before": "Responder imediatamente com qualquer coisa para não ficar em silêncio.", "after": "Vou separar duas questões. Sobre a primeira, o que os dados permitem dizer é...", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Sorteie uma pergunta do modo de ensaio.", "Faça uma pausa e escolha uma ideia.", "Responda em 60 segundos com um exemplo.", "Repita em 30 segundos, preservando o ponto central."], "check": {"question": "Você recebe uma pergunta ambígua. Qual é uma resposta útil?", "options": ["Responder o que vier à cabeça.", "Pedir uma breve especificação.", "Inventar um exemplo para ganhar tempo."], "correct": 1, "feedback": "Esclarecer a pergunta melhora a pertinência da resposta."}, "rubric": ["A resposta aborda a pergunta.", "Há uma ideia principal.", "Os limites do conhecimento foram respeitados."], "module": "Prática e autonomia", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L17", "title": "Perguntas difíceis e objeções", "minutes": 60, "outcome": "Dominar perguntas críticas com calma: limites, incerteza e decisão.", "study": ["Gestor testa: custo, evidência, prazo, responsabilidade.", "Você precisa nomear limites sem perder autoridade: ‘o que sabemos’, ‘o que não sabemos’, ‘o que recomendamos mesmo assim’.", "Repetir a decisão ajuda a manter o foco.", "Use linguagem de risco: probabilidade, severidade, custo de oportunidade.", "Objetivo: você sair como ‘profissional confiável’."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Diga limites sem se desculpar.", "Traga recomendação prática apesar da incerteza.", "Traduza estatística em decisão."], "dont": ["Não se esconda atrás de jargão.", "Não prometa o que não tem.", "Não vire defensivo."]}, "templates": [{"name": "Limite + recomendação", "text": "O que sabemos: ________.\nO que ainda é incerto: ________.\nMesmo assim, recomendamos: ________ (porque ________)."}], "tasks": ["Escreva 3 perguntas ‘duras’ e responda com o template.", "Refine para tom calmo e firme.", "Cole a melhor na Entrega."], "theory": ["Uma pergunta difícil pode apontar uma falha real, uma dúvida de linguagem ou uma divergência de valores. Escute até o fim e identifique qual dessas situações está em jogo. Repetir a pergunta de modo breve ajuda a confirmar o entendimento e permite que toda a sala acompanhe.", "Responda ao núcleo antes de acrescentar detalhes. Quando houver uma crítica válida, reconheça-a e explique seu efeito sobre a conclusão. Se a pergunta extrapolar o estudo, diga onde termina a evidência. “Não tenho esse dado agora” é uma resposta mais confiável que uma precisão inventada. Prometa um retorno apenas se houver condições de realizá-lo.", "Em situações hostis, mantenha limites de respeito. É possível discordar sem desqualificar a pessoa. A mediação do evento pode ajudar a distribuir tempo e interromper agressões. Prepare perguntas difíceis durante o ensaio: sobre amostra, viés, generalização, causalidade, custo e aplicabilidade. A meta é esclarecer, não vencer uma disputa."], "example": {"before": "Essa pergunta não faz sentido e meu resultado está certo.", "after": "A questão sobre a amostra é pertinente. Ela limita a generalização desta forma...", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Liste cinco objeções plausíveis.", "Escreva uma resposta direta para cada uma.", "Marque onde você precisaria consultar uma fonte.", "Ensaie com alguém fazendo perguntas de acompanhamento."], "check": {"question": "Uma crítica identifica uma limitação real. O que fazer?", "options": ["Negá-la para preservar autoridade.", "Reconhecer e explicar o que ela muda na conclusão.", "Mudar de assunto imediatamente."], "correct": 1, "feedback": "Reconhecer limites fortalece a precisão e permite uma discussão útil."}, "rubric": ["A pergunta foi compreendida.", "A resposta reconhece limites pertinentes.", "O tom mantém respeito e objetividade."], "module": "Prática e autonomia", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L18", "title": "Nervosismo e preparação possível", "minutes": 60, "outcome": "Ter um protocolo pré-palestra de 5 min que estabiliza corpo e voz.", "study": ["Nervosismo é energia. O problema é falta de direção.", "Protocolo 5 min: respiração (1 min) + postura (1 min) + frase de abertura (2 min) + pausa (1 min).", "Seu corpo aprende por repetição, não por vontade.", "Autoconfiança = evidência interna: ‘eu já fiz isso 10 vezes’.", "Meta: reduzir sintomas em 30–50% com rotina."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Faça protocolo antes de qualquer fala.", "Treine abertura diariamente por 3 min.", "Use pausas para controlar ansiedade."], "dont": ["Não ‘apague’ nervosismo com pressa.", "Não se ataque mentalmente.", "Não mude tudo em cima da hora."]}, "templates": [{"name": "Protocolo 5 min", "text": "1) Respiração (1 min): ________\n2) Postura (1 min): ________\n3) Abertura (2 min): ________\n4) Pausa (1 min): ________\nMeta: começar com calma e clareza."}], "tasks": ["Escreva seu protocolo pessoal.", "Execute hoje antes de falar 30s (qualquer tema).", "Cole o protocolo final na Entrega."], "theory": ["Falar em público pode trazer desconforto. O curso propõe práticas de preparação e ensaio, sem diagnosticar ansiedade nem substituir atendimento profissional. Comece com uma situação manejável: uma gravação individual, depois uma pessoa conhecida, depois um pequeno grupo. Ajuste a dificuldade ao que é viável para você.", "Uma rotina prévia reduz tarefas de última hora. Confira o arquivo, o equipamento, a água, o roteiro e o horário. Escolha a primeira frase e saiba qual é a mensagem central. Durante a fala, uma pausa para reorganizar o pensamento é aceitável. Se perder o ponto, retome a pergunta do bloco em vez de pedir desculpas repetidamente.", "Observe o que funcionou além do que incomodou. Uma sensação intensa de nervosismo não prova que o público deixou de compreender. Avalie evidências concretas, como clareza da mensagem e cumprimento do tempo. Se o sofrimento for persistente, intenso ou impedir atividades importantes, buscar ajuda qualificada é um caminho apropriado."], "example": {"before": "Se eu ficar nervoso, a palestra estará arruinada.", "after": "Posso estar desconfortável e ainda seguir meu roteiro, fazer uma pausa e comunicar a ideia.", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Escreva uma rotina simples de preparação.", "Ensaie a primeira frase e a retomada de um bloco.", "Faça uma rodada curta numa situação confortável.", "Registre uma coisa que funcionou e um ajuste possível."], "check": {"question": "Qual avaliação é mais útil depois do ensaio?", "options": ["Julgar tudo apenas pela sensação de nervosismo.", "Observar clareza, tempo e compreensão, além da sensação.", "Concluir que um erro torna toda a apresentação inútil."], "correct": 1, "feedback": "Critérios observáveis ajudam a avaliar a comunicação sem reduzir tudo ao desconforto."}, "rubric": ["Existe uma rotina viável.", "A retomada foi ensaiada.", "A avaliação considera comportamentos concretos."], "module": "Prática e autonomia", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L19", "title": "A palestra final", "minutes": 60, "outcome": "Montar talk final: abertura, 3 blocos, 2 exemplos, fecho e CTA.", "study": ["Aqui você junta tudo: mensagem, estrutura, exemplos, voz e fecho.", "Você vai produzir um talk que dá orgulho e é repetível.", "Seu talk precisa funcionar para público misto: academia + gestão + sociedade.", "Checklist: abertura 30s, blocos claros, 2 exemplos fortes, fecho 25s, CTA executável.", "Objetivo: você sair com um talk ‘assinatura’."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Tenha 1 slide por ideia.", "Use 2 exemplos fortes.", "Feche com CTA e prazo."], "dont": ["Não tente colocar tudo que você sabe.", "Não fale 25 min se prometeu 12.", "Não termine sem próximo passo."]}, "templates": [{"name": "Roteiro talk final (12–15 min)", "text": "Abertura (30s): ________\nBloco 1: ________\nExemplo 1: ________\nBloco 2: ________\nExemplo 2: ________\nBloco 3: ________\nFecho (25s): ________\nCTA (prazo): ________"}], "tasks": ["Preencha o roteiro talk final completo.", "Fale 12–15 min (cronometre).", "Cole link/roteiro final na Entrega."], "theory": ["A atividade final reúne mensagem, evidência, estrutura e presença. Escolha um público e uma duração compatíveis com seu objetivo. Use uma apresentação real, mas confira se você tem autorização para compartilhar imagens e informações. Prepare um roteiro com as ideias de cada slide, em vez de transcrever um artigo inteiro.", "Faça uma rodada completa, incluindo abertura, transições, conclusão e perguntas. Registre o tempo e verifique quais partes ficaram difíceis. Uma gravação só ajuda quando você a revê com critérios: o público consegue identificar a mensagem? As figuras têm contexto? As conclusões respeitam as evidências? O encerramento orienta um próximo passo?", "Peça a uma pessoa que avalie a mesma fala usando os mesmos critérios. Compare as observações sem transformar a nota em competição. Escolha mudanças prioritárias e grave novamente. Guarde o roteiro, a versão dos slides e uma breve reflexão. A conclusão do curso representa uma atividade formativa autodeclarada; não é uma certificação profissional externa."], "example": {"before": "Concluir o curso porque todos os links foram abertos.", "after": "Apresentar uma fala completa, receber feedback e revisar mensagem, evidências e tempo.", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Importe e revise sua apresentação.", "Ensaie a duração completa e uma versão curta.", "Responda a três perguntas difíceis.", "Entregue o roteiro final e uma reflexão sobre as mudanças."], "check": {"question": "O que demonstra melhor o aproveitamento do curso?", "options": ["Abrir todos os materiais sem praticar.", "Acumular horas com o cronômetro aberto.", "Realizar, avaliar e revisar uma apresentação completa."], "correct": 2, "feedback": "A prática revisada permite integrar as habilidades trabalhadas."}, "rubric": ["A palestra tem começo, desenvolvimento e fechamento.", "As afirmações têm sustentação e limites.", "O feedback gerou uma revisão concreta."], "module": "Prática e autonomia", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}, {"id": "L20", "title": "Seu plano de continuidade: 30 dias", "minutes": 60, "outcome": "Criar um manual pessoal e um plano de 30 dias para virar hábito.", "study": ["Oratória vira ‘você’ quando vira rotina curta.", "Manual pessoal: seus 5 princípios + seus 3 erros + seu protocolo + sua frase-marca.", "Plano 30 dias: 10 min por dia, 4 micro-metas por semana.", "Você vai ter orgulho: ‘estudei sozinho com plataforma que construí’.", "Agora você pode ensinar — porque viveu o método."], "links": [{"label": "Toastmasters — preparação de uma fala (em inglês)", "url": "https://www.toastmasters.org/resources/public-speaking-tips/preparing-a-speech", "note": "Leitura complementar; o conteúdo da aula está disponível nesta plataforma."}, {"label": "COMPASS — comunicação científica e público (em inglês)", "url": "https://www.compassscicomm.org/leadership-development/the-message-box/", "note": "Referência externa complementar. Materiais e direitos pertencem à organização."}], "doDont": {"do": ["Faça microtreinos diários de 10 min.", "Refaça seu talk final 1x por semana.", "Peça feedback específico (clareza/CTA)."], "dont": ["Não deixe 2 semanas sem falar.", "Não mude tudo de uma vez.", "Não pare no ‘agora tá bom’."]}, "templates": [{"name": "Manual pessoal (1 página)", "text": "Meus 5 princípios: (1) ___ (2) ___ (3) ___ (4) ___ (5) ___\nMeus 3 erros: ___ / ___ / ___\nMeu protocolo 5 min: ________\nMinha frase-marca: ________\nMeu CTA padrão: ________"}, {"name": "Plano 30 dias", "text": "Semana 1: ________\nSemana 2: ________\nSemana 3: ________\nSemana 4: ________\nMeta final (talk): ________"}], "tasks": ["Complete seu manual pessoal (copie no template).", "Complete o plano de 30 dias.", "Cole o manual + plano na Entrega."], "theory": ["A prática fica mais útil quando cabe na rotina. Escolha uma habilidade prioritária e defina sessões curtas com uma entrega observável. Na primeira semana, trabalhe mensagem e abertura. Na segunda, explique figuras e transições. Na terceira, pratique adaptação de público e perguntas. Na quarta, apresente uma versão completa e compare com a inicial.", "Use materiais reais do seu trabalho para que o treino produza algo reaproveitável. Não precisa gravar uma palestra longa todos os dias. Dois minutos bem observados podem revelar um ajuste importante. Alterne ensaio individual e retorno de outras pessoas quando isso for possível. Guarde versões datadas para acompanhar mudanças.", "Ao final dos trinta dias, avalie o que melhorou, o que continua difícil e qual será o próximo ciclo. Compare tarefas semelhantes e preserve critérios. O plano é ajustável: interrupções não anulam o trabalho realizado. A finalidade é ganhar recursos para comunicar com clareza em contextos variados, não eliminar todo erro ou reproduzir o estilo de outro palestrante."], "example": {"before": "Vou treinar quando tiver tempo e tentar melhorar tudo.", "after": "Nesta semana, farei três ensaios de dois minutos para explicar uma figura com clareza.", "label": "Exemplo didático de formulação; não representa um resultado de pesquisa."}, "practiceSteps": ["Defina uma habilidade e três sessões semanais possíveis.", "Escolha uma entrega por semana.", "Agende uma conversa de feedback.", "Compare a fala inicial e a final com a mesma rubrica."], "check": {"question": "Qual plano tende a ser mais executável?", "options": ["Melhorar tudo imediatamente.", "Treinar apenas na véspera de um grande evento.", "Definir sessões possíveis, uma habilidade e uma entrega observável."], "correct": 2, "feedback": "Um plano concreto facilita executar e avaliar a prática."}, "rubric": ["O plano cabe na rotina.", "As entregas são observáveis.", "Há uma comparação e um próximo ciclo."], "module": "Prática e autonomia", "schedule": [{"label": "Leitura e compreensão", "minutes": 10}, {"label": "Análise do exemplo", "minutes": 10}, {"label": "Prática e produção", "minutes": 25}, {"label": "Revisão e feedback", "minutes": 10}, {"label": "Reflexão e registro", "minutes": 5}]}], "totalHours": 20, "description": "20 aulas com carga de prática sugerida de 1h cada. O tempo de leitura isolado é menor que a carga total; materiais externos são opcionais."};
